import pandas as pd
import numpy as np

# Load all available experiments
exps = {}
for i in [1, 2, 4, 5]:
    fname = f"experiment_{i}_csv"
    df = pd.read_csv(globals()[fname])
    exps[f"exp{i}"] = df
    print(f"\n=== EXPERIMENT {i} ===")
    print(f"Shape: {df.shape}")
    print(f"Columns: {list(df.columns)}")
    print(f"\nSummary of key columns:")
    for col in ['CropYield', 'LeafGreennessIndex', 'EC_Salinity', 'PARLight', 'DissolvedO2Nutrient']:
        if col in df.columns:
            print(f"  {col}: mean={df[col].mean():.2f}, std={df[col].std():.2f}, min={df[col].min():.2f}, max={df[col].max():.2f}")

    # Show any intervention columns
    int_cols = [c for c in df.columns if any(k in c.lower() for k in ['iron', 'ph', 'chelate', 'nitrogen', 'potassium', 'magnesium', 'light', 'dose', 'add'])]
    if int_cols:
        print(f"\nIntervention columns: {int_cols}")
        for c in int_cols:
            print(f"  {c}: mean={df[c].mean():.2f}, values={df[c].unique()}")

# Check correlations in each experiment
for name, df in exps.items():
    num_cols = df.select_dtypes(include=[np.number]).columns.tolist()
    if len(num_cols) >= 3:
        print(f"\n=== {name} CORRELATIONS with CropYield ===")
        if 'CropYield' in num_cols:
            cy_corr = df[num_cols].corr()['CropYield'].drop('CropYield').sort_values(ascending=False)
            print(cy_corr.round(3))

print("Available vars:", [k for k in globals().keys() if not k.startswith('_') and 'experiment' in k])
for k in globals().keys():
    if 'experiment' in k:
        print(f"{k} = {globals()[k]}")
